{"candidate_version": 2, "candidate_sha256": "5f3f5d4f1e512caffe090ab1c5cbddc22993b18b0e998d33e95687d7ac2bdce7", "review_request_id": "review:a256db8451a1bd894062c370d787a3a58c1c4bd0b5cb534863dcd3c0d6089547", "full_candidate": "@prefix sh:   <http://www.w3.org/ns/shacl#> .
